{
  "name": "opencode-model-tracker",
  "version": "1.2.1",
  "description": "OpenCode plugin for tracking model, agent, token, cost, and quality metrics locally.",
  "type": "module",
  "license": "MIT",
  "author": "qtsone",
  "homepage": "https://github.com/qtsone/opencode-model-tracker#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/qtsone/opencode-model-tracker.git"
  },
  "bugs": {
    "url": "https://github.com/qtsone/opencode-model-tracker/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "model-tracker",
    "llm",
    "telemetry",
    "sqlite"
  ],
  "exports": {
    ".": "./src/index.js",
    "./server": "./src/index.js"
  },
  "files": [
    "src",
    "models.example.json",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=22.5.0"
  },
  "scripts": {
    "test": "node --test tests/*.test.js",
    "audit:high": "npm audit --audit-level=high",
    "pack:dry-run": "npm pack --dry-run",
    "check:private-paths": "node scripts/check-private-paths.js"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.14.33"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  }
}
